function compress(s) {
  const parts = []
  let i = 0
  while (i < s.length) {
    let j = i
    while (j < s.length && s[j] === s[i]) j++
    parts.push(s[i], String(j - i))
    i = j
  }
  const out = parts.join('')
  return out.length < s.length ? out : s
}

